from pathlib import Path
import csv,json,struct,hashlib
from unicorn import *
from unicorn.x86_const import *
R=Path(__file__).resolve().parents[1];b=(R/'baseline48/prior/inputs/nite3w - 110.exe').read_bytes();assert hashlib.sha256(b).hexdigest()=='12fe5168783446275802e0e947898261b5eca6b88288f3a895fc1faa4c544481'
rows=list(csv.DictReader(open(R/'baseline48/pass48-results/listing.tsv'),delimiter='\t'))
code=bytearray(b[0x4c0:0x4c0+0xdce2]);patches=[]
for r in rows:
 if r['function'] in ['1000:036a','1000:4542','1000:4582','1000:45be']:
  off=int(r['address'][5:],16);v=bytes.fromhex(r['bytes']);code[off:off+len(v)]=v
for r in rows:
 if r['address'].startswith('1000:') and r['instruction'].startswith('CALLF 0x10'):
  off=int(r['address'][5:],16);v=bytes.fromhex(r['bytes']);assert v[0]==0x9a
  target=int.from_bytes(v[3:5],'little');new={0x1000:0x2000,0x1008:0x3000}.get(target)
  if new:code[off+3:off+5]=struct.pack('<H',new);patches.append(hex(off))
results=[]
for head in [0,0x6000,0xffff]:
 for ptr in range(0x4608,0x4689,4):
  u=Uc(UC_ARCH_X86,UC_MODE_16);u.mem_map(0,0x100000);u.mem_write(0x20000,bytes(code));u.mem_write(0x30000,b[0xe8a0:0xe8a0+0x73fe]);u.mem_write(0x10480,b[0x2c040:0x2c040+0x8eae])
  def w(o,v):u.mem_write(0x10480+o,struct.pack('<H',v))
  def rd(o):return struct.unpack('<H',u.mem_read(0x10480+o,2))[0]
  w(0x4fe,head);w(0xa96,ptr);u.mem_write(0x40000+0xd000,struct.pack('<HH',0x100,0xf000))
  for reg,val in [(UC_X86_REG_CS,0x2000),(UC_X86_REG_DS,0x1048),(UC_X86_REG_SS,0x4000),(UC_X86_REG_SP,0xd000),(UC_X86_REG_BP,0xbeef)]:u.reg_write(reg,val)
  seen=[]
  def hook(u,a,n,x):
   seen.append(a)
   if a==0xf0100:u.emu_stop()
  u.hook_add(UC_HOOK_CODE,hook);u.emu_start(0x245ce,0,count=1000)
  assert seen[-1]==0xf0100
  assert [rd(x) for x in [0x4fe,0x50e,0x522,0x532]]==[0x524,head,0x500,0x514]
  assert [rd(x) for x in [0x41bc,0x41be,0x41c2,0x41c4]]==[0x48e4,0x1018,0x48f8,0x1018]
  assert u.reg_read(UC_X86_REG_SP)==0xd004 and u.reg_read(UC_X86_REG_BP)==0xbeef
  assert rd(0xa96)==ptr+(4 if ptr!=0x4688 else 0)
  if ptr!=0x4688:assert [rd(ptr),rd(ptr+2)]==[0x45a4,0x1000]
  assert u.reg_read(UC_X86_REG_AX)==(0 if ptr!=0x4688 else 0xffff)
  results.append({'initial_head':hex(head),'exit_pointer':hex(ptr),'ax':hex(u.reg_read(UC_X86_REG_AX)),'instructions':len(seen)-1})
out={'cases_passed':len(results),'cases':results,'normalizations':'CALLF selectors in segment 1: 1000=>2000,1008=>3000, based on native export. 036a/4542/4582/45be bytes normalized from native listing first, including selector immediates and callback PUSH. Stored callback selector remains original 1000. No imported calls reached, no stubs.','patch_sites':patches}
(R/'pass69/verification.json').write_text(json.dumps(out,indent=2));print('PASS',len(results))
